
const $=id=>document.getElementById(id),arrows=['⬆','➡','⬇','⬅'];let p,blocks=[],robot,queue=[],index=0,drag=-1;
function sample(){p={start:30,goal:5,dir:0,walls:[8,9,14,20,26]};blocks=[];reset();drawBlocks()}
function reset(){anim=null;robot={pos:p.start,dir:p.dir};queue=[];index=0;board();$('status').textContent='準備完了'}
let canvas=null,ctx=null,camera=0.72,dragCamera=null,anim=null,frame=0,visual={pos:30,dir:0};
const dirs=[[0,-1],[1,0],[0,1],[-1,0]];
function project(x,y,z=0){let u=x-2.5,v=y-2.5,c=Math.cos(camera),sn=Math.sin(camera);return {x:310+(u*c-v*sn)*66,y:229+(u*sn+v*c)*31-z*48}}
function poly(pts,fill,stroke='#7897b2'){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.2;ctx.stroke()}}
function face(points,color){poly(points.map(v=>project(...v)),color)}
function box3(x,y,w,h,z0,z1,top,side){let corners=[[x-w/2,y-h/2],[x+w/2,y-h/2],[x+w/2,y+h/2],[x-w/2,y+h/2]];let surfaces=[];surfaces.push({pts:corners.map(v=>[...v,z1]),fill:top});for(let i=0;i<4;i++){let j=(i+1)%4,aa=corners[i],bb=corners[j],center=[(aa[0]+bb[0])/2,(aa[1]+bb[1])/2],out=[center[0]-x,center[1]-y],view=[Math.sin(camera),Math.cos(camera)];if(out[0]*view[0]+out[1]*view[1]>0)surfaces.push({pts:[[...aa,z0],[...bb,z0],[...bb,z1],[...aa,z1]],fill:i%2?side:'#668ba7'})}surfaces.forEach(v=>face(v.pts,v.fill))}
function arrowAt(x,y,dir){let [dx,dy]=dirs[dir],base=project(x,y,0.18),tip=project(x+dx*.43,y+dy*.43,.18),tail=project(x-dx*.2,y-dy*.2,.18);ctx.strokeStyle='#e15e42';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(tail.x,tail.y);ctx.lineTo(tip.x,tip.y);ctx.stroke();let ang=Math.atan2(tip.y-base.y,tip.x-base.x);ctx.fillStyle='#e15e42';ctx.beginPath();ctx.moveTo(tip.x+Math.cos(ang)*4,tip.y+Math.sin(ang)*4);ctx.lineTo(tip.x-Math.cos(ang-.65)*15,tip.y-Math.sin(ang-.65)*15);ctx.lineTo(tip.x-Math.cos(ang+.65)*15,tip.y-Math.sin(ang+.65)*15);ctx.fill()}
function drawRobot(x,y,d){let q=project(x,y,.05);ctx.fillStyle='#294e7355';ctx.beginPath();ctx.ellipse(q.x,q.y,20,9,0,0,Math.PI*2);ctx.fill();box3(x,y,.43,.43,0,.47,'#53b8e7','#2273b5');box3(x,y,.52,.46,.49,.9,'#e3f8ff','#77c7e5');let dir=Math.round(d)%4;arrowAt(x,y,dir);let [dx,dy]=dirs[dir],front=project(x+dx*.27,y+dy*.27,.72);ctx.fillStyle='#103f67';ctx.beginPath();ctx.arc(front.x,front.y,5,0,Math.PI*2);ctx.fill();let antenna=project(x,y,1.08),head=project(x,y,.91);ctx.strokeStyle='#e55f48';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(head.x,head.y);ctx.lineTo(antenna.x,antenna.y);ctx.stroke();ctx.fillStyle='#ffcf55';ctx.beginPath();ctx.arc(antenna.x,antenna.y,4,0,Math.PI*2);ctx.fill()}
function scene(){
 if(!ctx)return;
 ctx.clearRect(0,0,620,470);
 // Render all ground tiles first: ground must never cover a moving robot.
 for(let i=0;i<36;i++){
  let x=i%6,y=Math.floor(i/6);
  let pts=[[x-.5,y-.5,0],[x+.5,y-.5,0],[x+.5,y+.5,0],[x-.5,y+.5,0]].map(v=>project(...v));
  poly(pts,i===p.goal?'#ffe5a2':i===p.start?'#b9efd0':(x+y)%2?'#e0eef8':'#cce2f3');
  if(i===p.goal){let q=project(x,y,.08);ctx.fillStyle='#f3a918';ctx.font='bold 27px system-ui';ctx.textAlign='center';ctx.fillText('★',q.x,q.y+9)}
 }
 let x=visual.pos%6,y=Math.floor(visual.pos/6),d=visual.dir;
 if(anim){let t=Math.min(1,(performance.now()-anim.start)/360),ease=t*t*(3-2*t);x=anim.from%6+(anim.to%6-anim.from%6)*ease;y=Math.floor(anim.from/6)+(Math.floor(anim.to/6)-Math.floor(anim.from/6))*ease;d=anim.dirTo;if(t>=1)anim=null}
 // Only elevated objects participate in depth sorting, preserving wall occlusion.
 let objects=[];
 for(let i of p.walls){let wx=i%6,wy=Math.floor(i/6);objects.push({depth:project(wx,wy).y,draw:()=>box3(wx,wy,.92,.92,0,.85,'#a9c3d5','#789ab4')})}
 objects.push({depth:project(x,y).y,draw:()=>drawRobot(x,y,d)});
 objects.sort((a,b)=>a.depth-b.depth);objects.forEach(o=>o.draw());
 if(anim){cancelAnimationFrame(frame);frame=requestAnimationFrame(scene)}
}
function board(){if(!canvas){let root=$('board');root.replaceChildren();canvas=document.createElement('canvas');canvas.width=620;canvas.height=470;canvas.style.width='100%';canvas.style.display='block';canvas.style.touchAction='none';canvas.setAttribute('aria-label','ドラッグで視点を回転できる立体ロボット迷路');root.append(canvas);ctx=canvas.getContext('2d');canvas.addEventListener('pointerdown',e=>{dragCamera={id:e.pointerId,x:e.clientX,start:e.clientX,y:e.clientY,old:camera,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragCamera||dragCamera.id!==e.pointerId)return;let delta=e.clientX-dragCamera.start;if(Math.abs(delta)>5||Math.abs(e.clientY-dragCamera.y)>5)dragCamera.moved=true;if(dragCamera.moved){camera=dragCamera.old+delta*.012;scene()}});canvas.addEventListener('pointerup',e=>{if(!dragCamera)return;let moved=dragCamera.moved;dragCamera=null;if(moved||$('mode').value!=='edit')return;let rect=canvas.getBoundingClientRect(),px=(e.clientX-rect.left)*620/rect.width,py=(e.clientY-rect.top)*470/rect.height;let best=-1,dist=1e9;for(let i=0;i<36;i++){let q=project(i%6,Math.floor(i/6));let v=((q.x-px)/43)**2+((q.y-py)/25)**2;if(v<dist){dist=v;best=i}}if(dist<1.8)paint(best)});canvas.addEventListener('pointercancel',()=>dragCamera=null)}if(!anim)visual={pos:robot.pos,dir:robot.dir};scene()}
function animateRobot(before){visual={pos:robot.pos,dir:robot.dir};if(before.pos!==robot.pos){anim={from:before.pos,to:robot.pos,dirTo:robot.dir,start:performance.now()};scene()}else scene()}

function paint(i){if($('mode').value!=='edit')return;let t=$('paint').value;if(t==='start'){p.start=i;p.walls=p.walls.filter(x=>x!==i);if(p.goal===i)p.goal=-1}else if(t==='goal'){p.goal=i;p.walls=p.walls.filter(x=>x!==i);if(p.start===i)p.start=-1}else if(t==='wall'){if(i!==p.start&&i!==p.goal&&!p.walls.includes(i))p.walls.push(i)}else p.walls=p.walls.filter(x=>x!==i);reset()}
function drawBlocks(){let w=$('workspace');w.replaceChildren();blocks.forEach((c,i)=>{let d=document.createElement('div');d.className='block';d.draggable=true;d.ondragstart=()=>drag=i;d.ondragover=e=>e.preventDefault();d.ondrop=e=>{e.preventDefault();let x=blocks.splice(drag,1)[0];blocks.splice(i,0,x);drawBlocks()};let name=document.createElement('span');name.textContent={F:'⬆ 前進',L:'↶ 左回転',R:'↷ 右回転',T:'🔁 繰り返し'}[c.type];d.append(name);if(c.type==='T'){let n=document.createElement('input');n.type='number';n.min=1;n.max=20;n.value=c.count;n.style.width='55px';n.onchange=()=>c.count=Math.max(1,Math.min(20,Number(n.value)||1));d.append(n);let s=document.createElement('select');for(let t of ['F','L','R']){let o=document.createElement('option');o.value=t;o.textContent={F:'前進',L:'左回転',R:'右回転'}[t];s.append(o)}s.value=c.inner;s.onchange=()=>c.inner=s.value;d.append(s)}let x=document.createElement('button');x.textContent='削除';x.onclick=()=>{blocks.splice(i,1);drawBlocks()};d.append(x);w.append(d)});if(!blocks.length)w.textContent='ここに命令ブロックが並びます'}
function compile(){queue=[];for(let c of blocks){let n=c.type==='T'?c.count:1;for(let i=0;i<n;i++){queue.push(c.type==='T'?c.inner:c.type);if(queue.length>300)throw Error('命令数は300までです')}}}
function tick(){if(index>=queue.length){$('status').textContent=robot.pos===p.goal?'成功！':'命令終了。もう少し考えてみよう';return false}let before={...robot};let t=queue[index++];if(t==='L')robot.dir=(robot.dir+3)%4;if(t==='R')robot.dir=(robot.dir+1)%4;if(t==='F'){let x=robot.pos%6,y=Math.floor(robot.pos/6);if(robot.dir===0)y--;if(robot.dir===1)x++;if(robot.dir===2)y++;if(robot.dir===3)x--;if(x<0||x>5||y<0||y>5||p.walls.includes(y*6+x)){$('status').textContent='壁にぶつかった！ '+index+'命令目';board();index=queue.length;return false}robot.pos=y*6+x}animateRobot(before);$('status').textContent=index+' / '+queue.length+' 命令';if(robot.pos===p.goal){$('status').textContent='成功！ '+index+'命令でゴール！';index=queue.length;return false}return true}
function prepare(){reset();try{compile();return true}catch(e){$('status').textContent=e.message;return false}}
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{blocks.push(b.dataset.type==='T'?{type:'T',count:2,inner:'F'}:{type:b.dataset.type});drawBlocks()});$('run').onclick=async()=>{if(!prepare())return;let button=$('run');button.disabled=true;try{while(tick()){await new Promise(r=>setTimeout(r,420))}}finally{button.disabled=false}};$('step').onclick=()=>{if(!queue.length||index>=queue.length){if(!prepare())return}tick()};$('reset').onclick=reset;$('clear').onclick=()=>{blocks=[];drawBlocks();reset()};$('mode').onchange=()=>{$('editor').hidden=$('mode').value!=='edit';reset()};$('direction').onchange=()=>{p.dir=Number($('direction').value);reset()};$('sample').onclick=sample;
function valid(x){return x&&Number.isInteger(x.start)&&x.start>=0&&x.start<36&&Number.isInteger(x.goal)&&x.goal>=0&&x.goal<36&&x.start!==x.goal&&[0,1,2,3].includes(x.dir)&&Array.isArray(x.walls)&&x.walls.every(i=>Number.isInteger(i)&&i>=0&&i<36&&i!==x.start&&i!==x.goal)}
$('save').onclick=()=>{if(!valid(p)){alert('スタートとゴールを別のマスに置いてください');return}localStorage.setItem('resoarc-robot-problem',JSON.stringify(p));$('status').textContent='保存しました'};$('load').onclick=()=>{try{let x=JSON.parse(localStorage.getItem('resoarc-robot-problem'));if(!valid(x))throw Error();p=x;reset()}catch{alert('保存問題が見つかりません')}};$('export').onclick=async()=>{if(!valid(p))return alert('問題を完成させてください');let s=JSON.stringify(p);try{await navigator.clipboard.writeText(s);$('status').textContent='問題データをコピーしました'}catch{prompt('コピーしてください',s)}};$('import').onclick=()=>{try{let x=JSON.parse(prompt('問題データを貼り付けてください'));if(!valid(x))throw Error();p=x;reset()}catch{alert('問題データが正しくありません')}};sample();
